var setPieceRoomHost=null,setPieceRoomMarkup=null,setPieceRoomScene='corner';
function renderSetPieceRoom(){
 if(view!=='match'||matchPopupActive!=='setpieces'||!state)return;
 const host=$('match-popup-setpieces'),campaign=state===season.match,d=SetPieceRoom.read(state,{preferences:campaign?season.plan.setPieces:{}});if(!host||!d)return;
 const esc=escapeText,html='<article class="set-piece-room"><header>'+ClubArt.deadball(setPieceRoomScene)+'<div><small>한 번의 킥, 함께 만든 약속</small><h3>멈춘 공에서 만드는 기회</h3><p>'+(d.editable?'세 역할을 정하고 킥오프를 준비하세요.':d.finished?'종료 시점 담당 · 경기 기록은 결과에서 확인하세요.':'현재 필드의 담당 · 교체·퇴장 시 자동 대체')+'</p></div></header><div class="deadball-roles">'+d.roles.map(r=>'<section class="deadball-role"><h4>'+r.label+'</h4><div class="deadball-person">'+(r.selected?Portraits.html(F.identityProfile(r.selected.identity))+'<div><b>'+esc(r.selected.name)+'</b><span>지표 <strong>'+r.selected.score+'</strong> · 체력 '+r.selected.energy+'</span></div>':'<p>필드에 담당 선수가 없습니다.</p>')+'</div><small class="deadball-weights">'+r.weights+'</small>'+(d.editable?'<select data-deadball-role="'+r.role+'" aria-label="'+r.label+' 선택"><option value="auto" '+(campaign&&!r.preference?'selected':'')+'>선발에서 자동 선택</option>'+r.candidates.map(p=>'<option value="'+p.id+'" '+((!campaign||r.preference)&&p.id===r.selected?.id?'selected':'')+'>'+esc(p.name)+' · '+p.score+' · 체력 '+p.energy+'</option>').join('')+'</select>':'<small class="deadball-locked">킥오프 전 변경 가능</small>')+'<small class="deadball-preference">'+esc(r.fallback?r.preference.name+' 대신 현재 대체 담당':r.preference?'우선 담당: '+r.preference.name:campaign?'선발에서 자동 선택':'연습 경기 담당')+'</small></section>').join('')+'</div><p class="deadball-note">지표는 능력 가중치이며 득점 확률이 아닙니다. '+(d.editable?'선택은 즉시 저장됩니다.':'닫은 뒤 경기는 직접 이어가세요.')+'</p><p id="deadball-save-status" class="deadball-save-status" role="status" aria-live="polite"></p></article>';
 if(setPieceRoomHost===host&&setPieceRoomMarkup===html)return;host.innerHTML=html;setPieceRoomHost=host;setPieceRoomMarkup=html;
 host.onchange=event=>{const select=event.target.closest('[data-deadball-role]');if(!select||!host.contains(select))return;const role=select.dataset.deadballRole;setPieceRoomScene=role==='freeKick'?'freeKick':'corner';
  try{if(state!==season.match)F.assignSetPieceRole(state,role,select.value==='auto'?F.defaultSetPieces(state,state.lineup)[role]:select.value);else if(select.value==='auto')S.autoSetPiece(season,role);else S.assignSetPiece(season,role,select.value);save();render();renderSetPieceRoom();host.querySelector('[data-deadball-role="'+role+'"]')?.focus({preventScroll:true});const current=SetPieceRoom.read(state).roles.find(r=>r.role===role);$('deadball-save-status').textContent=current.label+' · '+current.selected.name+(canSave?' 저장 완료':' 적용 · 저장 실패, 저장 상태를 확인하세요.');}catch(error){notify(error.message);setPieceRoomMarkup=null;renderSetPieceRoom();}
 };
}
const deadballOriginalPopup=renderMatchPopup;renderMatchPopup=function(){deadballOriginalPopup();renderSetPieceRoom();};
const deadballShortcut=document.createElement('button');deadballShortcut.type='button';deadballShortcut.className='deadball-shortcut';deadballShortcut.dataset.matchPopup='setpieces';deadballShortcut.textContent='세트피스 작전실 · 키커와 타깃';$('match-popup-tactics').prepend(deadballShortcut);
